import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the authoritative golden vectors generated by `color_matching`.
///
/// The fixture is intentionally read from the repository rather than generated
/// here: an update must come from `viamin/color_matching`'s deterministic
/// `mix parity.generate` task, so this test detects solver-contract drift.
final class SolverParityCorpusTests: XCTestCase {
    func testWeightedSquaredErrorMatchesParityCorpus() throws {
        let corpusURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/weighted_squared_error_v1.json")

        guard FileManager.default.fileExists(atPath: corpusURL.path) else {
            XCTFail("Missing committed parity corpus at \(corpusURL.path). Refresh it from viamin/color_matching#111.")
            return
        }

        let corpus = try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: corpusURL))
        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")

        for scenario in corpus.scenarios {
            try assertScenario(scenario)
        }
    }

    private func assertScenario(_ scenario: ParityScenario) throws {
        let weights = ChannelWeights(channels: scenario.weights)
        let target = TargetResponseVector(channels: scenario.target.channels)
        let palette = scenario.palette.map(makeColor)
        let scorer = WeightedSquaredErrorScorer()

        for (candidate, expected) in zip(palette, scenario.expected.scores) {
            XCTAssertEqual(candidate.id, expected.index, scenario.id)
            switch (scorer.score(candidate: candidate, target: target, weights: weights), expected.score) {
            case (.excluded, .excluded):
                break
            case (.score(let actual), .value(let expected)):
                XCTAssertEqual(actual, expected, scenario.id)
            default:
                XCTFail("\(scenario.id): score mismatch for palette index \(candidate.id)")
            }
        }

        guard scenario.target.hasEveryPositiveWeightChannel(in: weights) else {
            XCTAssertNil(scenario.expected.selectedIndex, scenario.id)
            return
        }

        let grids = try sourceGrids(from: scenario.target.channels, weights: weights)
        let result = try CompositionSolver().solve(palette: palette, sourceGrids: grids, weights: weights)
        XCTAssertEqual(result.colorIndex(x: 0, y: 0), scenario.expected.selectedIndex, scenario.id)

        if let expectedError = scenario.expected.error {
            XCTAssertEqual(result.error(x: 0, y: 0), expectedError, scenario.id)
        } else {
            XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, scenario.id)
        }
    }

    private func makeColor(_ vector: ParityVector) -> PaletteColor {
        let responses = vector.channels.reduce(into: [LightingCondition: IlluminationResponse]()) { responses, entry in
            if let condition = LightingCondition(rawValue: entry.key) {
                responses[condition] = IlluminationResponse(brightness: entry.value)
            }
        }
        return PaletteColor(
            id: vector.index ?? -1,
            hex: vector.hexColor,
            rgb: RGBColor(hex: vector.hexColor)!,
            responses: responses
        )
    }

    private func sourceGrids(
        from channels: [String: Double],
        weights: ChannelWeights
    ) throws -> [LightingCondition: BrightnessGrid] {
        try weights.activeEntries.reduce(into: [:]) { grids, entry in
            let value = try XCTUnwrap(channels[entry.condition.rawValue])
            grids[entry.condition] = BrightnessGrid(width: 1, height: 1, values: [value])
        }
    }
}

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let palette: [ParityVector]
    let target: ParityVector
    let weights: [String: Double]
    let expected: ParityExpectation
}

private struct ParityVector: Decodable {
    let channels: [String: Double]
    let hexColor: String
    let index: Int?
}

private struct ParityExpectation: Decodable {
    let error: Double?
    let scores: [ParityScore]
    let selectedIndex: Int?
}

private struct ParityScore: Decodable {
    let index: Int
    let score: ParityScoreValue
}

private enum ParityScoreValue: Decodable {
    case excluded
    case value(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .value(value)
        } else if try container.decode(String.self) == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Expected a score or excluded")
        }
    }
}

private extension ChannelWeights {
    init(channels: [String: Double]) {
        self.init(
            white: channels["white", default: 0],
            red: channels["red", default: 0],
            green: channels["green", default: 0],
            blue: channels["blue", default: 0],
            lps: channels["lps", default: 0]
        )
    }
}

private extension TargetResponseVector {
    init(channels: [String: Double]) {
        self.init(channels.reduce(into: [LightingCondition: Double]()) { values, entry in
            if let condition = LightingCondition(rawValue: entry.key) {
                values[condition] = entry.value
            }
        })
    }
}

private extension ParityVector {
    func hasEveryPositiveWeightChannel(in weights: ChannelWeights) -> Bool {
        weights.activeEntries.allSatisfy { channels[$0.condition.rawValue] != nil }
    }
}
